from alembic import command

from tests.conftest import alembic_config


def test_migrations_downgrade_and_upgrade_cleanly(migrated_database: str) -> None:
    config = alembic_config()
    command.downgrade(config, "base")
    command.upgrade(config, "head")


def test_models_and_migrations_have_no_drift(migrated_database: str) -> None:
    # Raises AutogenerateDiffsDetected if the models and the migrations disagree.
    command.check(alembic_config())
